// Generated by `just generate` from `src/plugins/claudetto/slices/setup/domain/settings.ts`. Edit the source and run `just generate`.
// The settings step of setup, as pure functions: which file a scope names, and the merge plan for a settings object.
// The CLI reads and writes the files.

import { DOCS_SNIPPET } from "../prompts.ts";
import { planAutoMode } from "./automode.ts";
import {
  FABLE,
  foreignStatusLines,
  isObject,
  MYTHOS,
  mergeSettings,
  snippetFor,
} from "./merge.ts";
import { planSigningKey } from "./sandbox.ts";
import type { Change, InstalledPlugins, Json, UserSettings } from "./types.ts";

/** True when the user settings or the installed plugins name `claudetto-docs`. */
export const hasDocsAddon = (
  userSettings: UserSettings,
  installed: InstalledPlugins,
): boolean => {
  const id = "claudetto-docs@claudetto";
  return (
    userSettings?.enabledPlugins?.[id] === true ||
    Object.hasOwn(installed?.plugins ?? {}, id)
  );
};

/**
 * True when the parsed model catalog that the API served to the account offers `MYTHOS`.
 * Claude Code 2.1.301 caches the catalog in `<config dir>/cache/model-catalog/<organizationUuid>-<hash>-<surface>.json`.
 * Its `isMythosAvailable` takes a Mythos row of `catalog.config.models` that is not `disabled` and not in the `deprecated` section.
 * The file is not documented, so another shape gives false.
 */
export const mythosOffered = (data: unknown): boolean => {
  const models = isObject(data)
    ? (data["catalog"] as Json | undefined)?.["config"]
    : undefined;
  const list = isObject(models) ? models["models"] : undefined;
  return (
    Array.isArray(list) &&
    list.some(
      (m) =>
        isObject(m) &&
        m["id"] === MYTHOS &&
        m["disabled"] !== true &&
        m["section"] !== "deprecated",
    )
  );
};

/** The options of `planSettings`. */
export type SettingsOptions = {
  /** Adds `DOCS_SNIPPET`. */
  withDocs: boolean;
  /** Puts `MYTHOS` in place of `FABLE`. The CLI sets it from `mythosOffered`. */
  mythos?: boolean;
  /** Leaves out the status line keys, because their command holds an absolute path of this computer. */
  skipStatusLines?: boolean;
  /** Merges the `autoMode` lists of `planAutoMode`. Only the user settings take them. */
  autoMode?: boolean;
  /** Merges the tier picks of `picksOf` after the snippet. Setup writes none when the account has no login. */
  picks?: Json | undefined;
  /** Sets `advisorModel` to `advisorOf` the merged settings. Setup sets it only when the user asks, because each request then has about 1,358 tokens more. */
  advisor?: boolean;
  /** The value of `git config user.signingkey`. A key file goes to `sandbox.filesystem.allowRead`. */
  signingKey?: string | undefined;
  /** The value of `SSH_AUTH_SOCK`. With a key file, its folder goes to `sandbox.network.allowUnixSockets`. */
  agentSocket?: string | undefined;
};

/** The model for `advisorModel`: `MYTHOS` when `availableModels` of `settings` holds it, else `FABLE`. */
export const advisorOf = (settings: Json): string => {
  const list = settings["availableModels"];
  return Array.isArray(list) && list.includes(MYTHOS) ? MYTHOS : FABLE;
};

/**
 * The merged settings of `current` and the change lines.
 * `root` is the folder of the plugin, and `kept` names the status line keys of another tool that stay.
 * Throws when `current` is not an object.
 */
export const planSettings = (
  current: unknown,
  root: string,
  {
    withDocs,
    mythos = false,
    skipStatusLines = false,
    autoMode = false,
    picks,
    advisor = false,
    signingKey,
    agentSocket,
  }: SettingsOptions,
): { settings: Json; changes: string[]; kept: string[] } => {
  if (!isObject(current)) throw new Error("The settings are not an object.");
  const changes: Change[] = [];
  let settings = mergeSettings(
    current,
    snippetFor(current, root, mythos, skipStatusLines),
    "",
    changes,
  ).settings;
  if (withDocs)
    settings = mergeSettings(
      settings,
      DOCS_SNIPPET as Json,
      "",
      changes,
    ).settings;
  if (picks) settings = mergeSettings(settings, picks, "", changes).settings;
  if (autoMode) settings = planAutoMode(settings, changes);
  settings = planSigningKey(settings, signingKey, changes, agentSocket);
  if (advisor)
    settings = mergeSettings(
      settings,
      { advisorModel: advisorOf(settings) },
      "",
      changes,
    ).settings;
  return {
    settings,
    changes: changes.map((c) => c.line),
    kept: skipStatusLines ? [] : foreignStatusLines(current),
  };
};
